const $=s=>document.querySelector(s), h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M5 12h14m-5-5 5 5-5 5',up:'M6 18 18 6M6 6h12v12',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z m-5 10 3 3 5-6',store:'M3 10v11h18V10 M2 10l3-7h14l3 7c-2 4-4 3-5 0-1 3-3 3-5 0-2 3-4 3-5 0-1 3-3 4-5 0 M9 21v-7h6v7',phone:'M8 2H4C1 13 11 23 22 20v-4l-5-2-3 3-7-7 3-3Z',phones:'M7 2h10v20H7Z M10 18h4',audio:'M3 15v-3a9 9 0 0 1 18 0v3 M3 12h4v9H3Z M17 12h4v9h-4Z',laptops:'M4 3h16v14H4Z M1 21h22l-3-4H4Z',chargers:'M9 2v6 M15 2v6 M6 8h12v4a6 6 0 0 1-12 0Z M12 18v4',appliances:'m13 2-9 12h7l-1 8 10-13h-7Z',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10',info:'M12 11v6m0-10v1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',nav:'m3 10 18-7-7 18-3-8Z',list:'M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1',map:'m2 5 6-3 8 3 6-3v17l-6 3-8-3-6 3Z M8 2v17M16 5v17',filter:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6M10 15v6',x:'m6 6 12 12M6 18 18 6',refresh:'M20 7V2l-3 3a9 9 0 1 0 3 13 M20 2h-5',plus:'M12 4v16M4 12h16',locate:'M12 2v3m0 14v3M2 12h3m14 0h3 M19 12a7 7 0 1 1-14 0 7 7 0 0 1 14 0',alert:'m12 2 11 20H1Z M12 9v5m0 3v1'};
const icon=(name,size=20)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.store}"/></svg>`;
const categories=[['phones','Phones'],['audio','Audio'],['laptops','Laptops'],['chargers','Chargers & Cables'],['appliances','Appliances']];
const money=(n,c='INR')=>new Intl.NumberFormat(c==='INR'?'en-IN':'en-US',{style:'currency',currency:c,maximumFractionDigits:0}).format(n);
const page=location.pathname.split('/')[1]||'home',entityId=decodeURIComponent(location.pathname.split('/')[2]||''),params=new URLSearchParams(location.search);
const S={user:null,firstAdmin:false,catalogue:[],q:params.get('q')||'',category:params.get('category')||'',currency:localStorage.getItem('currency')||'INR',lat:Number(params.get('lat')||32.7266),lng:Number(params.get('lng')||74.857),area:'Jammu, India',radius:'5',sort:'best',stock:false,open:false,negotiable:false,min:'',max:'',listings:[],products:[],entity:null,workspace:null,busy:false,error:'',map:false,filters:false,shopQuery:'',locationMessage:'',signup:false,adminTab:'overview',ownerShop:'',report:null,edit:null};
let recent=[];try{recent=JSON.parse(localStorage.getItem('recent')||'[]');}catch{}let timer,requestId=0;
document.documentElement.dataset.theme=localStorage.getItem('theme')||'light';
async function api(path,b){const r=await fetch('/api/'+path,b?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}:{cache:'no-store'});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||'Please check the highlighted rows.'),{details:d});return d;}
function toast(message){const t=$('#toast');t.innerHTML=icon('check')+`<span>${h(message)}</span>`;t.className='visible';clearTimeout(timer);timer=setTimeout(()=>t.className='',5000);}
function nav(){return `<header class="topbar"><div class="shell nav"><a class="brand" href="/"><span class="brandmark">${icon('pin',28)}</span><span>nearby<small>stock finder</small></span></a><nav aria-label="Main navigation"><a class="${['home','search','products','shops'].includes(page)?'active':''}" href="/">Find a product</a><a href="/availability">How it works</a><a href="/for-shops">For shop owners</a></nav><div class="nav-actions"><label class="sr-only" for="currency">Listing currency</label><select id="currency"><option ${S.currency==='INR'?'selected':''}>INR</option><option ${S.currency==='USD'?'selected':''}>USD</option></select><button class="icon-button" data-action="theme" aria-label="Toggle dark mode">${icon('moon',18)}</button><a class="button small owner-link" href="/owner">${icon('store',17)}My shop</a></div></div></header>${!navigator.onLine?'<div class="offline" role="status">You’re offline. Reconnect to check current availability. Recent searches are saved on this device.</div>':''}`;}
function footer(){return `<footer><div class="shell footer-grid"><div><a class="brand" href="/">${icon('pin',25)}nearby</a><p>Know before you go.<br>Built for local discovery in Jammu.</p></div><div><strong>Find your way</strong><a href="/about">About</a><a href="/availability">How availability works</a><a href="/for-shops">For shop owners</a></div><div><strong>A little more</strong><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/contact">Contact</a></div><div><strong>Local workspace</strong><a href="/owner">Shop dashboard</a><a href="/admin">Admin</a><a href="/design-system">Design system</a></div></div><div class="shell footer-bottom"><span>© ${new Date().getFullYear()} Nearby Stock Finder</span><span>Local preview · sample data is labelled</span></div></footer>`;}
function searchbox(){return `<form id="search-form" class="searchbox">${icon('search',23)}<div class="searchinput"><label for="product-search" class="sr-only">Search electronics</label><input id="product-search" name="q" placeholder="What are you looking for? e.g. iPhone 15" value="${h(S.q)}" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="suggestions"><div id="suggestions" class="suggestions" role="listbox" hidden></div></div><button class="primary">Search ${icon('arrow',18)}</button></form>`;}
function locationControl(){return `<details class="location-control"><summary>${icon('pin',17)}<span>${h(S.area)}</span><span class="tiny">Change</span></summary><div class="location-panel"><button data-action="locate">${icon('locate',17)}Use my location</button><form id="area-form"><label>Or enter area / pincode<input name="area" placeholder="Gandhi Nagar or 180004" required></label><button>Apply area</button></form><p class="muted">${h(S.locationMessage||'Your precise location is used only for this search.')}</p></div></details>`;}
function home(){return `<section class="hero"><div class="shell hero-grid"><div><div class="eyebrow"><span class="live-dot"></span>YOUR LOCAL ELECTRONICS FINDER</div><h1>Find it nearby.<br><span>Know before you go.</span></h1><p class="hero-copy">The right product. A shop around the corner.<br class="desktop"> Check prices and recently confirmed stock in Jammu.</p>${searchbox()}<div class="hero-location">${locationControl()}<span>Launching in Jammu</span></div><div class="popular"><span>Try searching</span>${['iPhone 15','boAt Airdopes','MacBook Air'].map(s=>`<button data-search="${h(s)}">${h(s)} ${icon('up',13)}</button>`).join('')}</div></div><div class="hero-visual"><div class="mini-grid"><div class="map-river"></div><span class="map-label label-a">JAMMU</span><span class="map-label label-b">GANDHI NAGAR</span><span class="map-label label-c">TAWI RIVER</span><span class="you-pin">${icon('locate',24)}</span>${['a','b','c'].map(x=>`<span class="shop-pin pin-${x}">${icon('store',19)}</span>`).join('')}</div><div class="visual-card"><span class="visual-icon">${icon('shield',27)}</span><div><strong>Less guessing. Better trips.</strong><p>Check the confirmation time<br>before you head out.</p></div>${icon('check',22)}</div><div class="visual-note">Illustration · explore locations in search results</div></div></div></section><div class="trust-line shell">${icon('shield',18)}<p>Stock info is confirmed by shops and shoppers. <a href="/availability">Check the time stamp.</a></p><span>Local shops. Clear information.</span></div><section class="shell section"><div class="section-heading"><div><span class="eyebrow muted">START WITH WHAT YOU NEED</span><h2>Explore electronics</h2></div><a href="/search?category=phones">Browse products ${icon('arrow',17)}</a></div><div class="category-grid">${categories.map(([id,name],i)=>`<a class="category-card cat-${i}" href="/search?category=${id}"><span class="category-art">${icon(id,50)}<i></i></span><strong>${name}</strong><span>Find nearby ${icon('up',15)}</span></a>`).join('')}</div></section>${recent.length?`<section class="shell recent"><h3>Recently searched</h3><div class="chips">${recent.map(q=>`<button data-search="${h(q)}">${icon('clock',15)}${h(q)}</button>`).join('')}<button data-action="clear-history">Clear history</button></div></section>`:''}<section class="shell section how"><div class="section-heading"><div><span class="eyebrow muted">A LITTLE CHECK GOES A LONG WAY</span><h2>From search to storefront</h2></div><a href="/availability">How availability works ${icon('arrow',17)}</a></div><div class="steps">${[['search','01','Find your product','Search a model or browse a category. Pick the area that works for you.'],['clock','02','Check the details','Compare prices, distance, and when each shop last confirmed its stock.'],['nav','03','Make your next move','Call to double-check, then get directions straight to the shop.']].map(([i,n,t,p])=>`<div><span class="step-icon">${icon(i,23)}</span><span class="step-number">${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></section><section class="shell owner-banner"><div class="owner-graphic">${icon('store',46)}</div><div><span class="eyebrow">FOR THE SHOPS THAT MAKE JAMMU</span><h2>Your next customer is already nearby.</h2><p>List your products. Confirm stock in a tap. Help people find your shop.</p></div><a class="button primary" href="/join">List your shop ${icon('up',18)}</a></section>`;}
function empty(title,description,button=''){return `<div class="empty">${icon('search',35)}<h2>${h(title)}</h2><p>${h(description)}</p>${button}</div>`;}
function skeleton(){return `<div aria-busy="true" aria-label="Loading shops">${[1,2,3].map(()=>'<div class="skeleton"></div>').join('')}</div>`;}
function directions(s){return s.sample?'<span class="sample">Demo location · do not visit</span>':`<a class="button primary" href="https://www.google.com/maps/dir/?api=1&destination=${s.lat},${s.lng}" target="_blank" rel="noreferrer" data-direction="${h(s.id)}">${icon('nav',17)}Get directions</a>`;}
function card(l,showProduct=true){const a=l.availability;return `<article class="listing-card"><div class="listing-main"><div class="store-icon">${icon(l.product.category_id,29)}</div><div class="listing-name">${showProduct?`<a class="product-link" href="/products/${h(l.product_id)}">${h(l.product.name)}</a>`:''}<a class="shop-name" href="/shops/${h(l.shop_id)}">${h(l.shop.name)} ${icon('shield',17)}</a><div class="meta"><span>${l.distance.toFixed(1)} km away</span><span class="${l.open?'open':'muted'}">${l.open?'Open now':'Closed now'}</span><span>${l.rating?l.rating.toFixed(1)+' ('+l.reviewCount+' reviews)':'No reviews yet'}</span></div><p class="address">${h(l.shop.area)}, ${h(l.shop.city)}</p>${l.sample?'<span class="sample">Sample listing · simulated stock and price</span>':''}</div><div class="price"><strong>${money(l.price_min,l.currency)}${l.price_max&&l.price_max!==l.price_min?'–'+money(l.price_max,l.currency):''}</strong>${l.negotiable?'<small>Negotiable</small>':''}</div></div><div class="stock-row"><span class="badge ${a.key}">${icon(a.key==='in_stock'?'check':a.key==='stale'?'clock':'alert',14)}${h(a.label)}</span><span class="${a.caution?'caution':'muted'}">${icon('clock',14)}${h(a.confirmation)}</span>${a.stale?`<small class="muted">Last reported: ${h(a.lastReported)}</small>`:''}${a.hidden?'<span class="badge stale">Possibly outdated</span>':''}${a.community?`<small class="community">${h(a.community)}</small>`:''}</div><div class="listing-actions"><details class="rank"><summary>${icon('info',14)}Why this rank?</summary><div class="rank-popover"><strong>Best match: ${l.rank.score}/100</strong>${Object.entries(l.rank.parts).map(([k,v])=>`<div><span>${k} (${{distance:40,freshness:35,rating:15,availability:10}[k]}%)</span><strong>${v.toFixed(1)}</strong></div>`).join('')}<p>Fresh in-stock, low-stock, stale, then out-of-stock groups. Scores order shops within each group. Ratings use a Bayesian average. Changing the sort changes the order.</p></div></details><button class="text-button" data-report="${h(l.id)}">Was it available? / Report</button>${directions(l.shop)}</div></article>`;}
function filters(){return `<aside class="filters ${S.filters?'show':''}"><h3>${icon('filter',18)}Refine your search</h3>${[['stock','In stock or low stock only'],['open','Open now'],['negotiable','Negotiable prices']].map(([k,t])=>`<label class="check"><input type="checkbox" data-filter="${k}" ${S[k]?'checked':''}>${t}</label>`).join('')}<label>Distance<select data-filter="radius">${[5,10,25,50].map(n=>`<option value="${n}" ${S.radius==n?'selected':''}>Within ${n} km</option>`).join('')}</select></label><label>Minimum price (${S.currency})<input type="number" min="0" data-filter="min" value="${h(S.min)}" placeholder="Any"></label><label>Maximum price (${S.currency})<input type="number" min="0" data-filter="max" value="${h(S.max)}" placeholder="Any"></label><button data-action="reset">Reset filters</button><div class="filter-note">${icon('info',20)}<p>Fresh information matters.<br>Older confirmations come with a caution.</p><a href="/availability">Understand the badges</a></div></aside>`;}
function searchPage(){const p=S.entity,title=page==='products'?(p?.name||'Product availability'):S.category?(categories.find(c=>c[0]===S.category)?.[1]||'Electronics'):S.q?`Results for “${S.q}”`:'Electronics near you';return `<div class="shell results-page"><div class="breadcrumb"><a href="/">Home</a><span>›</span><span>${page==='products'?'Product':'Search'}</span></div>${searchbox()}<div class="results-title"><div class="product-heading">${p?`<span class="product-image">${icon(p.category_id,43)}</span>`:''}<div><h1>${h(title)}</h1>${p?`<p>${h(JSON.parse(p.specs).summary)} ${p.sample?'<span class="sample">Sample catalogue</span>':''}</p>`:''}<div class="row muted">${locationControl()}<span>· ${S.listings.length} shop listings within ${S.radius} km</span></div></div></div><div class="view-toggle"><button data-action="list" aria-pressed="${!S.map}">${icon('list',18)}List</button><button data-action="map" aria-pressed="${S.map}">${icon('map',18)}Map</button></div></div><div class="results-layout">${filters()}<div><div class="results-toolbar"><button class="mobile-only" data-action="filters">${icon('filter',17)}Filters</button><span class="muted">Verified shops. Confirmation times always visible.</span><label class="sort">Sort by<select data-filter="sort">${[['best','Best match'],['nearest','Nearest'],['price','Lowest price'],['recent','Recently confirmed']].map(([v,t])=>`<option value="${v}" ${S.sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${S.busy?skeleton():S.error?empty('We couldn’t check availability',S.error,'<button data-action="retry">Try again</button>'):!S.listings.length?empty('No matching shops nearby',`No shops nearby list this in ${S.currency}. Try a wider radius or similar products. Currency selection does not convert prices.`,'<button data-action="widen">Search within 50 km</button>'):S.map?'<div id="shop-map" class="map-container" aria-label="Map of shop locations"></div><p class="muted">Map tiles require internet. Sample locations are illustrative.</p>':`<div class="listing-list">${S.listings.map(l=>card(l,page!=='products')).join('')}</div>`}${p&&S.listings.length?`<p class="muted">Listed prices: ${money(Math.min(...S.listings.map(l=>l.price_min)),S.currency)}–${money(Math.max(...S.listings.map(l=>l.price_max||l.price_min)),S.currency)}</p>`:''}<p class="results-foot">${icon('info',15)}Stock can change. Call the shop before a long trip.</p>${S.products.length&&page!=='products'?`<div class="related"><h3>Matching catalogue products</h3><div class="chips">${S.products.slice(0,16).map(p=>`<a href="/products/${h(p.id)}">${h(p.name)} ${icon('up',14)}</a>`).join('')}</div></div>`:''}</div></div></div>`;}
function shopPage(){if(S.busy)return '<div class="shell section">'+skeleton()+'</div>';if(!S.entity)return '<div class="shell section">'+empty('Shop unavailable',S.error||'This shop may be pending approval.')+'</div>';const s=S.entity,hours=JSON.parse(s.hours),photos=JSON.parse(s.photos||'[]'),ls=S.listings.filter(l=>l.currency===S.currency&&l.product.name.toLowerCase().includes(S.shopQuery.toLowerCase()));return `<div class="shell section"><div class="breadcrumb"><a href="/">Home</a><span>›</span><span>Shop details</span></div><div class="shop-header"><div class="shop-avatar">${icon('store',48)}</div><div><span class="verified">${icon('shield',16)}Verified shop</span><h1>${h(s.name)}</h1><p>${h(s.address)}</p>${s.sample?'<span class="sample">Sample shop · demo address and phone · do not visit</span>':''}</div><div class="stack">${directions(s)}${!s.sample?`<a class="button" href="tel:${h(s.phone)}">${icon('phone',17)}Call shop</a>`:''}</div></div>${photos.length?`<div class="shop-photos">${photos.map(p=>`<img src="${h(p)}" alt="Shop photo" loading="lazy">`).join('')}</div>`:''}<div class="shop-info"><div><h3>Opening hours</h3><p>${h(hours.open)}–${h(hours.close)} IST</p><p class="muted">Closed: ${h(hours.closed?.join(', ')||'No regular closing day')}</p></div><div><h3>Contact</h3><p>${s.sample?'Demo phone (unavailable)':h(s.phone)}</p><p class="muted">No reviews yet. Sample ratings are never generated.</p></div><div><h3>Location</h3><p>${h(s.area)}, ${h(s.city)}</p><a href="https://www.openstreetmap.org/?mlat=${s.lat}&mlon=${s.lng}#map=17/${s.lat}/${s.lng}" target="_blank" rel="noreferrer">View map pin ${icon('up',14)}</a></div></div><div class="section-heading"><h2>Electronics at this shop</h2><form id="shop-search"><input name="query" aria-label="Search shop products" placeholder="Search this shop" value="${h(S.shopQuery)}"><button>Search</button></form></div><div class="listing-list">${ls.map(l=>card(l)).join('')||empty('No matching listings','Try another product or currency.')}</div></div>`;}
function authBox(){return `<section class="shell auth-page"><span class="step-icon">${icon('store',28)}</span><h1>${S.signup?'Bring your shop to Nearby.':'Welcome back.'}</h1><p>Help customers find what’s on your shelves.</p><form id="auth-form" class="panel"><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" autocomplete="${S.signup?'new-password':'current-password'}" minlength="10" required></label><p class="muted tiny">Local development account · password is hashed and sessions stay on this device’s local server. Email delivery is not connected.</p>${S.firstAdmin?'<p class="notice">The first local account becomes this workspace’s admin.</p>':''}<p class="form-error" role="alert"></p><button class="primary">${S.signup?'Create local account':'Sign in'}</button><button type="button" class="text-button" data-action="auth-toggle">${S.signup?'Already have an account? Sign in':'New here? Create an account'}</button></form></section>`;}
function input(label,name,type='text',value='',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;}
function shopForm(field=false){return `<form id="shop-form" class="panel" data-field="${field}"><h2>${field?'Field agent: add a verified shop':'Tell shoppers about your shop'}</h2><div class="form-grid">${input('Shop name','name','text','','required maxlength="100"')}${input('Phone','phone','tel','','required placeholder="+91…"')}${input('Street address','address','text','','required maxlength="250"')}${input('Area','area','text','','required placeholder="Gandhi Nagar"')}${input('Latitude','lat','number','32.7266','required step="any"')}${input('Longitude','lng','number','74.857','required step="any"')}${input('Opens (IST)','open','time','10:00','required')}${input('Closes (IST)','close','time','20:00','required')}</div><div class="row"><button type="button" data-action="pin-current">${icon('locate',17)}Use shop’s current location</button><button type="button" data-action="pick-pin">${icon('map',17)}Pin shop on map</button></div><p id="pin-status" class="muted tiny">Use the map picker or GPS while at your shop. Coordinates remain editable.</p><fieldset><legend>Categories</legend><div class="chips">${categories.map(([id,t])=>`<label class="check"><input type="checkbox" name="categories" value="${id}" checked>${t}</label>`).join('')}</div></fieldset><label>Shop photo (optional)<input id="shop-photo" type="file" accept="image/*"></label><p class="muted tiny">Photos are resized to 1200 px and compressed before upload.</p><p class="form-error" role="alert"></p><button class="primary">${field?'Add verified shop':'Submit for approval'} ${icon('arrow',17)}</button></form>`;}
function listingForm(shopId,l=null){return `<form id="listing-form" class="panel"><h2>${l?'Edit listing':'Add a catalogue product'}</h2><input type="hidden" name="shop_id" value="${h(shopId)}">${l?`<input type="hidden" name="id" value="${h(l.id)}"><h3>${h(l.product.name)}</h3>`:`<label>Catalogue product<input id="catalogue-filter" placeholder="Filter by model or brand" autocomplete="off"><select name="product_id" id="product-options" size="5" required>${S.catalogue.map(p=>`<option value="${h(p.id)}">${h(p.name)}</option>`).join('')}</select></label>`}<div class="form-grid">${input('Price','price_min','number',l?.price_min||'','required min="0.01" step="0.01"')}${input('Maximum price (optional)','price_max','number',l?.price_max||'','min="0.01" step="0.01"')}<label>Currency<select name="currency"><option ${l?.currency!=='USD'?'selected':''}>INR</option><option ${l?.currency==='USD'?'selected':''}>USD</option></select></label><label>Availability<select name="status_reported">${[['in_stock','In stock'],['low_stock','Low stock'],['out_of_stock','Out of stock']].map(([v,t])=>`<option value="${v}" ${l?.status_reported===v?'selected':''}>${t}</option>`).join('')}</select></label>${input('Quantity (optional)','quantity','number',l?.quantity??'','min="0" step="1"')}<label class="check"><input type="checkbox" name="negotiable" ${l?.negotiable?'checked':''}>Price is negotiable</label></div><p class="form-error" role="alert"></p><button class="primary">${l?'Save and confirm':'Add product'} ${icon('check',17)}</button></form>`;}
function owner(){if(!S.user)return authBox();if(S.busy)return '<section class="shell section">'+skeleton()+'</section>';const d=S.workspace;if(!d)return '<section class="shell section">'+empty('Couldn’t load your workspace',S.error,'<button data-action="workspace-retry">Try again</button>')+'</section>';const s=d.shops.find(s=>s.id===S.ownerShop)||d.shops[0],ls=d.listings.filter(l=>l.shop_id===s?.id),fresh=ls.filter(l=>!l.availability.stale).length;return `<section class="shell section workspace"><div class="section-heading"><div><span class="eyebrow">YOUR SHOP WORKSPACE</span><h1>Keep your shelves in the picture.</h1><p class="muted">${h(S.user.email)} · ${h(S.user.role)}</p></div><button data-action="logout">Sign out</button></div>${!s||page==='join'?shopForm():`<div class="panel shop-select"><label>Shop<select id="owner-shop">${d.shops.map(v=>`<option value="${h(v.id)}" ${v.id===s.id?'selected':''}>${h(v.name)}</option>`).join('')}</select></label><span class="badge ${s.status==='verified'?'in_stock':'low_stock'}">${h(s.status)}</span><a href="/join">Add another shop</a></div>${s.status!=='verified'?`<p class="notice">${s.status==='pending'?'Your shop is awaiting admin approval. You can prepare listings; they appear in search after approval.':'Your shop is suspended. Contact your administrator.'}</p>`:''}<div class="stats"><div><strong>${ls.length}</strong><span>Product listings</span></div><div><strong>${ls.length?Math.round(fresh/ls.length*100):0}%</strong><span>Confirmed in last 7 days</span></div><div><strong>One tap</strong><span>To refresh every listing</span></div></div><div class="section-heading"><div><h2>Your products</h2><p class="muted">Review changed items first, then confirm everything else.</p></div><button class="primary" data-confirm-all="${h(s.id)}" ${s.status==='suspended'?'disabled':''}>${icon('check',18)}Confirm all still accurate</button></div><div class="owner-list">${ls.map(l=>`<article class="panel"><div class="section-heading"><div><h3>${h(l.product.name)}</h3><p>${money(l.price_min,l.currency)} · ${h(l.availability.confirmation)}</p><span class="badge ${l.availability.key}">${h(l.availability.label)}</span></div><button data-edit="${h(l.id)}">Edit price / details</button></div><div class="status-controls">${[['in_stock','In stock'],['low_stock','Low stock'],['out_of_stock','Out of stock']].map(([v,t])=>`<button class="${l.status_reported===v?'selected':''}" data-confirm="${h(l.id)}" data-status="${v}" data-shop="${h(s.id)}">${icon(v==='in_stock'?'check':'clock',16)}${t}</button>`).join('')}</div><details class="owner-rank"><summary>How my listing ranks: ${l.rank.score}/100</summary><p>Distance ${l.rank.parts.distance.toFixed(1)}/40 · Freshness ${l.rank.parts.freshness.toFixed(1)}/35 · Rating ${l.rank.parts.rating.toFixed(1)}/15 · Availability ${l.rank.parts.availability.toFixed(1)}/10.</p><p>Confirming accurate stock daily improves freshness. Fresh available listings appear ahead of stale listings.</p></details></article>`).join('')||empty('Your first product starts here','Choose a shared catalogue product below.')}</div>${listingForm(s.id)}`}</section>`;}
function adminPage(){if(!S.user)return authBox();if(S.user.role!=='admin')return '<section class="shell section">'+empty('Admin access required','This account can manage its own shops. The first local account is the workspace administrator.','<a class="button" href="/owner">My shop dashboard</a>')+'</section>';if(S.busy)return '<section class="shell section">'+skeleton()+'</section>';const d=S.workspace;if(!d)return '<section class="shell section">'+empty('Admin workspace unavailable',S.error,'<button data-action="workspace-retry">Retry</button>')+'</section>';const pending=d.shops.filter(s=>s.status==='pending'),unresolved=d.reports.filter(r=>!r.resolved_at),searches=d.logs.filter(l=>l.kind==='search');return `<section class="shell section workspace"><div class="section-heading"><div><span class="eyebrow">JAMMU OPERATIONS</span><h1>Keep local information useful.</h1><p class="muted">Approvals, reports, catalogue, and stock health.</p></div><button data-action="logout">Sign out</button></div><div class="stats"><div><strong>${pending.length}</strong><span>Awaiting approval</span></div><div><strong>${unresolved.length}</strong><span>Open reports</span></div><div><strong>${d.stale.length}</strong><span>Stale listings</span></div><div><strong>${searches.length?Math.round(searches.filter(l=>l.zero_result).length/searches.length*100):0}%</strong><span>Zero-result rate (latest searches)</span></div></div><div class="tabs">${['overview','shops','reports','catalogue','seed','field-agent'].map(t=>`<button data-tab="${t}" aria-pressed="${S.adminTab===t}">${t.replace('-',' ')}</button>`).join('')}</div>${S.adminTab==='overview'?`<div class="panel"><h2>Stock health</h2><p>${d.shops.filter(s=>s.status==='verified').length} verified shops · ${d.products.length} products · ${d.listings.length} listings</p><h3>Products people searched for but couldn’t find</h3>${d.logs.filter(l=>l.zero_result&&l.kind==='search').slice(0,15).map(l=>`<p>${h(l.query)} <small class="muted">${h(new Date(l.created_at).toLocaleString())}</small></p>`).join('')||'<p class="muted">No zero-result searches yet.</p>'}<h3>Stale listings</h3>${d.stale.slice(0,30).map(l=>`<p>${h(l.product.name)} · ${h(l.shop.name)} · ${h(l.availability.confirmation)}</p>`).join('')||'<p>Everything is recently confirmed.</p>'}<h3>Abuse signals</h3><p class="muted">Duplicate device/IP reports are blocked before insertion. Request limits protect reporting and sign-in. ${d.reports.length} accepted reports.</p><h3>Recent admin activity</h3>${d.actions.slice(0,10).map(a=>`<p>${h(a.kind)} · <small>${h(a.created_at)}</small></p>`).join('')}</div>`:''}${S.adminTab==='shops'?d.shops.map(s=>`<article class="panel section-heading"><div><h3>${h(s.name)}</h3><p>${h(s.address)}</p><span class="badge ${s.status==='verified'?'in_stock':'stale'}">${h(s.status)}</span>${s.sample?'<span class="sample">Sample</span>':''}</div><div class="row">${['verified','pending','suspended'].map(t=>`<button data-approve="${h(s.id)}" data-status="${t}">${t==='verified'?'Approve':t==='suspended'?'Suspend':'Set pending'}</button>`).join('')}</div></article>`).join(''):''}${S.adminTab==='reports'?unresolved.map(r=>`<article class="panel section-heading"><div><h3>${h(r.kind.replaceAll('_',' '))}</h3><p>Listing ${h(r.listing_id)} · ${h(r.created_at)}</p><small class="muted">Session ${h(r.device_hash.slice(0,10))} · network ${h(r.ip_hash.slice(0,10))}</small></div><button data-resolve="${h(r.id)}">Resolve</button></article>`).join('')||empty('No open reports','Customer reports will appear here.'):''}${S.adminTab==='catalogue'?`<form id="product-form" class="panel"><h2>Add a catalogue product</h2><div class="form-grid">${input('Brand','brand','text','','required')}${input('Model','model','text','','required')}${input('Specification summary','specs','text','','required')}${input('Aliases (comma-separated)','aliases')}<label>Category<select name="category_id">${categories.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label></div><p class="form-error" role="alert"></p><button class="primary">Add product</button></form><form id="merge-form" class="panel"><h2>Merge duplicate products</h2><p>Listings move to the retained product. The source product is archived.</p>${['source','target'].map(n=>`<label>${n==='source'?'Duplicate to merge':'Product to retain'}<select name="${n}">${d.products.map(p=>`<option value="${h(p.id)}">${h(p.name)}</option>`).join('')}</select></label>`).join('')}<p class="form-error" role="alert"></p><button>Merge products</button></form>`:''}${S.adminTab==='seed'?`<div class="panel"><h2>Sample marketplace</h2><p>20 clearly labelled sample shops, 80 sample products, simulated stock and prices. No invented reviews. Samples are never real places to visit.</p><div class="row"><button data-action="seed">Load sample data</button><button class="danger" data-action="remove-samples">Remove all sample data</button></div><p class="muted tiny">Removal archives samples in one action. It does not erase audit history. To restore archived samples, reset the local demo database after exporting any real records.</p></div><form id="import-form" class="panel"><h2>Admin seed import</h2><label>Import type<select name="type"><option value="shops">Shops</option><option value="listings">Listings</option></select></label><label>CSV file<input name="csv" type="file" accept=".csv,text/csv" required></label><p class="muted tiny">Shops: name,address,area,phone,lat,lng,open,close<br>Listings: shop_id,product_id,price_min,price_max,currency,status_reported,negotiable<br>Shop imports await approval. Maximum 300 rows. All rows validate before import.</p><div class="form-error" role="alert"></div><button class="primary">Validate and import</button></form>`:''}${S.adminTab==='field-agent'?shopForm(true):''}</section>`;}
const staticContent={about:['Local discovery, with fewer wasted trips.','Nearby Stock Finder helps people in Jammu choose which electronics shop to visit. Compare stock confirmation times, prices, and distance. Shops and shoppers contribute information; stock can change between a confirmation and your visit.','We are starting with electronics in one city. This local preview includes clearly labelled sample records for exploring the experience.'],availability:['What does “available” really mean?','Every listing shows the shop’s last confirmation time. A fresh confirmation is useful evidence, and never a guarantee.','0–48 hours: show the shop’s reported status. 48 hours–7 days: show that status with an older-confirmation caution. Over 7 days: “Not recently confirmed”, with the last reported status below it. Over 30 days: hide from default search; show “Possibly outdated” on the shop page.','A customer “available” report adds a separate community confirmation. It never resets the owner’s timestamp. Two independent out-of-stock reports within 48 hours flag the listing until the owner confirms again. One device or IP counts once.','Best match uses distance 40%, freshness 35%, Bayesian rating 15%, and availability 10%. Fresh in-stock listings rank ahead of low-stock, stale, and out-of-stock groups. “Why this rank?” shows each actual contribution. Explicit nearest/price/recent sorts use your selected order.'],privacy:['Your location is for finding a shop.','Precise search coordinates are used for the request and are not saved to your account. Area and recent search preferences stay in browser storage. Search text, result counts, and direction taps are stored without a visitor profile.','Reports use hashed session and network identifiers to limit duplicates and abuse. Owners’ account emails, hashed passwords, shop information, stock changes, and sessions are stored in the local SQLite database. Passwords use scrypt; session tokens are hashed.','This development instance stores data on this computer. No advertising trackers are installed. Contact your workspace administrator for data correction or removal. Clear recent searches from the home page.'],terms:['Check before making a long trip.','Listings are supplied by shops and shoppers. Availability, prices, opening hours, and distance estimates can change. Confirm important details with the shop. INR and USD selection filters listing currencies; it does not convert prices.','Only submit information you are authorized to share. Do not create misleading listings or abusive reports. Administrators may suspend shops and archive inaccurate records.','Sample shops, prices, and stock are simulations. Do not travel to sample locations or call demo phone numbers. This preview is for evaluating the product.'],contact:['Need to correct something?','For a listing issue, use “Was it available? / Report” on the listing. Shop owners can correct their products immediately from My shop.','For account or approval help, contact the person running this local workspace. A public support email has not been configured yet.'], 'for-shops':['Your next customer is already nearby.','Help people find the products you have in your physical shop. Create an account, submit your shop, then add products from the shared electronics catalogue. An administrator verifies your shop before it appears in search.','Once your products are listed, one tap confirms a status. “Confirm all still accurate” refreshes every listing after you have checked changes. Fresh, accurate listings rank higher.','Prices can be fixed, a range, or negotiable. INR and USD are stored per listing. There are no checkout, delivery, payment, or reservation flows.']};
function staticPage(){if(page==='design-system')return `<section class="shell prose section"><span class="eyebrow">DESIGN SYSTEM</span><h1>Clear enough to trust.</h1><p>Readable system sans serif, 16 px body, 44 px touch targets, 4/8/16/24/32/48 spacing. Green is the primary action accent. Status always includes text and an icon.</p><div class="swatches"><div style="background:#167451;color:white">Primary #167451</div><div style="background:#f0f6f2">Surface #f0f6f2</div><div style="background:#fff3d7">Caution #fff3d7</div></div><h2>Components</h2><div class="chips"><button class="primary">Primary action</button><button>Secondary action</button><span class="badge in_stock">${icon('check',14)}In stock</span><span class="badge low_stock">${icon('alert',14)}Low stock</span><span class="badge out_of_stock">${icon('x',14)}Out of stock</span><span class="badge stale">${icon('clock',14)}Not recently confirmed</span></div><h2>Type hierarchy</h2><h3>Shop name and product model</h3><p>Confirmation time and practical details.</p><small>Supplementary details use readable muted text.</small><h2>Interaction states</h2><div class="notice">Caution: confirmed 4 days ago.</div>${skeleton()}<button data-action="sample-toast">Preview toast</button><button data-action="sample-modal">Preview dialog</button></section>`;const c=staticContent[page];if(!c)return '<section class="shell section">'+empty('Page not found','Return home to find a product.','<a class="button" href="/">Back home</a>')+'</section>';return `<section class="shell prose section"><span class="eyebrow">${h(page.replace('-',' '))}</span><h1>${h(c[0])}</h1>${c.slice(1).map(p=>`<p>${h(p)}</p>`).join('')}${page==='for-shops'?'<a class="button primary" href="/join">List your shop →</a>':''}</section>`;}
function render(){const html=page==='home'?home():['search','products'].includes(page)?searchPage():page==='shops'?shopPage():['owner','join'].includes(page)?owner():page==='admin'?adminPage():staticPage();$('#app').innerHTML=nav()+`<main id="main">${html}</main>`+footer();if(S.map&&$('#shop-map'))drawMap($('#shop-map'),S.listings.map(l=>l.shop));}
async function loadSearch(){const rid=++requestId;S.busy=true;S.error='';render();const p=new URLSearchParams({q:page==='products'?'':S.q,currency:S.currency,radius:S.radius,sort:S.sort,lat:S.lat,lng:S.lng});if(page==='products')p.set('product',entityId);if(S.category)p.set('category',S.category);for(const k of ['stock','open','negotiable','min','max'])if(S[k])p.set(k,String(S[k]));try{const d=await api('search?'+p);if(rid!==requestId)return;S.listings=d.listings;S.products=d.products;}catch(e){S.error=e.message;}finally{if(rid===requestId){S.busy=false;render();}}}
async function loadWorkspace(){S.busy=true;S.error='';render();try{S.workspace=await api(page==='admin'?'admin':'owner');}catch(e){S.error=e.message;}finally{S.busy=false;render();}}
function search(q){q=q.trim();recent=[q,...recent.filter(r=>r!==q)].filter(Boolean).slice(0,6);localStorage.setItem('recent',JSON.stringify(recent));location.href='/search?'+new URLSearchParams({q,lat:String(S.lat),lng:String(S.lng)});}
function formObject(form){const f=new FormData(form),b=Object.fromEntries(f);b.negotiable=f.has('negotiable');b.categories=f.getAll('categories');return b;}
function openModal(html){const m=$('#modal');m.innerHTML=`<div class="modal-top"><button data-action="close-modal" aria-label="Close dialog">${icon('x',20)}</button></div>`+html;m.showModal();}
function parseCSV(source){const rows=[];let row=[],field='',quote=false;for(let i=0;i<source.length;i++){const c=source[i];if(c==='"'){if(quote&&source[i+1]==='"'){field+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(field.trim());field='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&source[i+1]==='\n')i++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}if(quote)throw new Error('CSV contains an unclosed quote.');row.push(field.trim());if(row.some(Boolean))rows.push(row);const header=rows.shift();if(!header||new Set(header).size!==header.length)throw new Error('CSV needs unique column headers.');return rows.map((r,i)=>{if(r.length!==header.length)throw new Error(`Row ${i+2}: column count does not match header.`);return Object.fromEntries(header.map((k,j)=>[k,r[j]]));});}
async function compressed(file){if(!file.type.startsWith('image/'))throw new Error('Choose an image file.');const image=await createImageBitmap(file),scale=Math.min(1,1200/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();return canvas.toDataURL('image/jpeg',.75);}
document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const b=formObject(form),err=form.querySelector('.form-error'),button=form.querySelector('button[type="submit"],button:not([type])');if(err)err.textContent='';try{if(form.id==='search-form')return search(b.q);if(form.id==='area-form'){const a=b.area.toLowerCase().trim(),areas={'jammu':[32.7266,74.857],'gandhi nagar':[32.703,74.862],'180004':[32.703,74.862],'jewel chowk':[32.727,74.850],'180001':[32.7266,74.857],'trikuta nagar':[32.688,74.883],'180020':[32.688,74.883],'channi himmat':[32.688,74.899],'talab tillo':[32.738,74.831]};if(!areas[a])throw new Error('Try Jammu, Gandhi Nagar, Jewel Chowk, Trikuta Nagar, Channi Himmat, Talab Tillo, or 180001 / 180004 / 180020.');[S.lat,S.lng]=areas[a];S.area=b.area;S.locationMessage='Using approximate area center.';if(['search','products'].includes(page))loadSearch();else render();return;}if(form.id==='shop-search'){S.shopQuery=b.query;return render();}if(button)button.disabled=true;
 if(form.id==='auth-form'){await api(S.signup?'auth/signup':'auth/login',b);location.href=page==='admin'?'/admin':'/owner';}
 if(form.id==='shop-form'){const file=$('#shop-photo')?.files?.[0];if(file){const r=await api('upload',{image:await compressed(file)});b.photos=[r.url];}await api(form.dataset.field==='true'?'admin/field-shop':'shops',b);toast(form.dataset.field==='true'?'Verified shop added. Add its products in My shop.':'Shop submitted. An admin can now approve it.');if(page==='join')location.href='/owner';else await loadWorkspace();}
 if(form.id==='listing-form'){await api(b.id?'listing-edit':'listings',b);$('#modal').close();toast('Listing saved and confirmed.');await loadWorkspace();}
 if(form.id==='report-form'){await api('reports',{listing_id:S.report.id,kind:b.kind});$('#modal').close();toast('Thank you. Your report has been counted.');if(page==='shops'){const d=await api('shops/'+entityId);S.listings=d.listings;render();}else await loadSearch();}
 if(form.id==='product-form'){await api('admin/product',b);S.catalogue=await api('catalogue');toast('Catalogue product added.');await loadWorkspace();}
 if(form.id==='merge-form'){await api('admin/merge',b);S.catalogue=await api('catalogue');toast('Duplicate merged into the retained product.');await loadWorkspace();}
 if(form.id==='import-form'){const file=form.querySelector('[name=csv]').files[0];const rows=parseCSV(await file.text());const d=await api('admin/import',{type:b.type,rows});toast(`Imported ${d.imported} rows.`);await loadWorkspace();}
 }catch(ex){const msg=ex.details?.errors?ex.details.errors.map(r=>`Row ${r.row}: ${r.error}`).join('\n'):ex.message;if(err)err.textContent=msg;else{S.locationMessage=msg;toast(msg);}}finally{if(button)button.disabled=false;}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='currency'){S.currency=t.value;localStorage.setItem('currency',t.value);if(['search','products'].includes(page))loadSearch();else render();}if(t.dataset.filter){S[t.dataset.filter]=t.type==='checkbox'?t.checked:t.value;loadSearch();}if(t.id==='owner-shop'){S.ownerShop=t.value;render();}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='product-search'){S.q=t.value;const suggestions=$('#suggestions');const list=S.catalogue.filter(p=>[p.name,...JSON.parse(p.aliases||'[]')].join(' ').toLowerCase().includes(t.value.toLowerCase())).slice(0,7);suggestions.innerHTML=list.map(p=>`<button type="button" role="option" data-search="${h(p.name)}">${icon(p.category_id,19)}<span>${h(p.name)}<small>${h(JSON.parse(p.specs).summary)}</small></span>${icon('up',16)}</button>`).join('');suggestions.hidden=!list.length||!t.value;t.setAttribute('aria-expanded',String(!suggestions.hidden));}if(t.id==='catalogue-filter'){$('#product-options').innerHTML=S.catalogue.filter(p=>p.name.toLowerCase().includes(t.value.toLowerCase())).map(p=>`<option value="${h(p.id)}">${h(p.name)}</option>`).join('');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#suggestions')){$('#suggestions').hidden=true;$('#product-search')?.setAttribute('aria-expanded','false');}if(e.target.id==='product-search'&&e.key==='ArrowDown'){e.preventDefault();$('#suggestions button')?.focus();}else if(e.target.closest('#suggestions')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();(e.key==='ArrowDown'?e.target.nextElementSibling:e.target.previousElementSibling)?.focus();}});
document.addEventListener('click',async e=>{const t=e.target.closest('button,a');if(!t)return;try{if(t.dataset.search!==undefined)return search(t.dataset.search);if(t.dataset.direction)api('direction-tap',{shop_id:t.dataset.direction}).catch(()=>{});if(t.dataset.report){S.report=S.listings.find(l=>l.id===t.dataset.report);openModal(`<h2>Help the next shopper</h2><p>${h(S.report.product.name)} at ${h(S.report.shop.name)}</p>${S.report.sample?'<p class="sample">Sample listing · reports affect demo confidence only</p>':''}<form id="report-form"><fieldset><legend>What did you find?</legend>${[['available','Yes, it was available'],['out_of_stock','I went, it was out of stock'],['wrong_price','The price was different'],['closed','Shop closed or moved'],['wrong_product','Wrong product']].map(([v,l],i)=>`<label class="check"><input type="radio" name="kind" value="${v}" ${!i?'checked':''}>${l}</label>`).join('')}</fieldset><p class="muted tiny">Your report never changes the shop’s confirmation time. Duplicate device/network reports count once.</p><p class="form-error" role="alert"></p><button class="primary">Submit report</button></form>`);return;}if(t.dataset.edit){const l=S.workspace.listings.find(l=>l.id===t.dataset.edit);return openModal(listingForm(l.shop_id,l));}if(t.dataset.confirm||t.dataset.confirmAll){t.disabled=true;await api('confirm',{shop_id:t.dataset.shop||t.dataset.confirmAll,listing_id:t.dataset.confirm,status:t.dataset.status});toast('Stock confirmed. Timestamp refreshed.');await loadWorkspace();}if(t.dataset.approve){await api('admin/shop',{id:t.dataset.approve,status:t.dataset.status});toast('Shop status updated.');await loadWorkspace();}if(t.dataset.resolve){await api('admin/resolve',{id:t.dataset.resolve});toast('Report resolved.');await loadWorkspace();}if(t.dataset.tab){S.adminTab=t.dataset.tab;render();}const a=t.dataset.action;if(a==='theme'){const v=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=v;localStorage.setItem('theme',v);}if(a==='clear-history'){recent=[];localStorage.removeItem('recent');render();}if(a==='map'||a==='list'){S.map=a==='map';render();}if(a==='filters'){S.filters=!S.filters;render();}if(a==='reset'){Object.assign(S,{stock:false,open:false,negotiable:false,min:'',max:'',radius:'5'});loadSearch();}if(a==='widen'){S.radius='50';loadSearch();}if(a==='retry')loadSearch();if(a==='workspace-retry')loadWorkspace();if(a==='auth-toggle'){S.signup=!S.signup;render();}if(a==='logout'){await api('auth/logout',{});location.href='/owner';}if(a==='close-modal')$('#modal').close();if(a==='sample-toast')toast('This is a confirmation message.');if(a==='sample-modal')openModal('<h2>Accessible dialog</h2><p>Focus stays inside this dialog. Press Escape to close.</p>');if(a==='seed'||a==='remove-samples'){await api('admin/'+a,{});S.catalogue=await api('catalogue');toast(a==='seed'?'Sample dataset loaded.':'Sample records archived.');loadWorkspace();}if(a==='pick-pin'){openModal('<h2>Pin your shop in Jammu</h2><p>Click the map to set coordinates. Use + and − to zoom.</p><div id="pin-map" class="map-container"></div>');drawMap($('#pin-map'),[],(lat,lng)=>{const f=$('#shop-form');f.elements.lat.value=lat.toFixed(6);f.elements.lng.value=lng.toFixed(6);$('#pin-status').textContent='Map pin selected.';$('#modal').close();});}if(a==='locate'||a==='pin-current'){if(!navigator.geolocation)throw new Error('Location is unavailable. Enter an area or coordinates.');t.disabled=true;navigator.geolocation.getCurrentPosition(p=>{if(a==='pin-current'){const f=$('#shop-form');f.elements.lat.value=p.coords.latitude.toFixed(6);f.elements.lng.value=p.coords.longitude.toFixed(6);$('#pin-status').textContent='GPS coordinates selected.';t.disabled=false;}else{S.lat=p.coords.latitude;S.lng=p.coords.longitude;S.area='Your current location';S.locationMessage='Location is used for this search only.';if(['search','products'].includes(page))loadSearch();else render();}},()=>{t.disabled=false;toast('Location unavailable. Enter your area/pincode, or pin the shop on the map.');},{timeout:10000,maximumAge:60000});}}catch(ex){toast(ex.message);t.disabled=false;}});
function drawMap(container,shops,pick){const unique=[...new Map(shops.map(s=>[s.id,s])).values()];let z=13,lat=unique[0]?.lat||32.7266,lng=unique[0]?.lng||74.857;function world(a,b){const n=2**z;return {x:(b+180)/360*n*256,y:(1-Math.asinh(Math.tan(a*Math.PI/180))/Math.PI)/2*n*256};}function inverse(x,y){const n=2**z;return {lng:x/256/n*360-180,lat:Math.atan(Math.sinh(Math.PI*(1-2*y/256/n)))*180/Math.PI};}function draw(){const w=container.clientWidth||600,ht=440,c=world(lat,lng),left=c.x-w/2,top=c.y-ht/2;let tiles='';for(let x=Math.floor(left/256);x<=Math.floor((left+w)/256);x++)for(let y=Math.floor(top/256);y<=Math.floor((top+ht)/256);y++)tiles+=`<img alt="" draggable="false" src="https://tile.openstreetmap.org/${z}/${x}/${y}.png" style="left:${x*256-left}px;top:${y*256-top}px" width="256" height="256">`;container.innerHTML=`<div class="map-tiles">${tiles}</div>${unique.map(s=>{const p=world(s.lat,s.lng);return `<a class="map-marker" style="left:${p.x-left}px;top:${p.y-top}px" href="/shops/${h(s.id)}" title="${h(s.name)}${s.sample?' · sample':''}" aria-label="${h(s.name)}${s.sample?' · sample':''}">${icon('store',19)}</a>`;}).join('')}<div class="map-controls"><button type="button" data-zoom="1" aria-label="Zoom in">+</button><button type="button" data-zoom="-1" aria-label="Zoom out">−</button><button type="button" data-pan="-1,0" aria-label="Pan left">←</button><button type="button" data-pan="1,0" aria-label="Pan right">→</button><button type="button" data-pan="0,-1" aria-label="Pan up">↑</button><button type="button" data-pan="0,1" aria-label="Pan down">↓</button></div><a class="map-attribution" href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">© OpenStreetMap contributors</a>`;container.onclick=e=>{const zoom=e.target.closest('[data-zoom]'),pan=e.target.closest('[data-pan]');if(zoom){z=Math.max(10,Math.min(18,z+Number(zoom.dataset.zoom)));draw();}else if(pan){const [x,y]=pan.dataset.pan.split(',').map(Number),p=inverse(c.x+x*128,c.y+y*128);lat=p.lat;lng=p.lng;draw();}else if(pick&&!e.target.closest('a,button')){const r=container.getBoundingClientRect(),p=inverse(left+e.clientX-r.left,top+e.clientY-r.top);pick(p.lat,p.lng);}};}draw();}
window.addEventListener('online',()=>{toast('You’re back online. Refresh availability before visiting.');render();});window.addEventListener('offline',render);
async function init(){render();const results=await Promise.allSettled([api('session'),api('catalogue')]);if(results[0].status==='fulfilled'){S.user=results[0].value.user;S.firstAdmin=results[0].value.firstAccountAdmin;}if(results[1].status==='fulfilled')S.catalogue=results[1].value;if(page==='join')S.signup=true;if(page==='products'){try{const d=await api('products/'+encodeURIComponent(entityId));S.entity=d.product;S.listings=d.listings;}catch(e){S.error=e.message;}}if(['search','products'].includes(page))await loadSearch();else if(page==='shops'){S.busy=true;render();try{const d=await api('shops/'+encodeURIComponent(entityId));S.entity=d.shop;S.listings=d.listings;}catch(e){S.error=e.message;}S.busy=false;render();}else if(['owner','join','admin'].includes(page)&&S.user)await loadWorkspace();else render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
init();
